def validate_requires_args(self, args):
    """Check if all the required arguments have been provided."""
    # `self.required_args` should be a sequence of argument names that are mandatory.
    required = getattr(self, "required_args", [])
    missing = []

    for name in required:
        # Accept both dict-like and sequence-like `args`.
        if isinstance(args, dict):
            if name not in args or args[name] is None:
                missing.append(name)
        else:
            # If `args` is a sequence, we assume the order matches `self.required_args`.
            # In this case, a missing value is represented by `None` or a missing index.
            try:
                idx = self.required_args.index(name)
                if idx >= len(args) or args[idx] is None:
                    missing.append(name)
            except ValueError:
                # name not found in required list – skip
                continue

    if missing:
        raise InvalidArgumentError(
            "Missing required argument(s): " + ", ".join(missing)
        )

